/**
 * Shared theme token system for the visual expansion.
 * Extends the existing AppSpecRenderer token pattern with ECharts-specific tokens.
 */

export interface ThemeTokens {
  // Card surface
  CARD_BG: string
  CARD_BORDER: string
  CARD_SHADOW: string

  // Tooltip
  TT_STYLE: Record<string, string | number>
  TT_LABEL: Record<string, string | number>

  // Text hierarchy
  textPrimary: string
  textSecondary: string
  textMuted: string
  textFaint: string

  // Grid / axes
  gridStroke: string
  gridStrokeOn: string
  axisTick: string
  axisLine: string
  splitLine: string

  // Surfaces
  headerBorder: string
  shimmerBg: string
  shimmerBg2: string
  rowAlt: string
  rowHover: string
  tableDivider: string

  // Canvas
  canvasBg: string
  dotGrid: string

  // KPI functions
  kpiBgFn: (color: string) => string
  kpiBorderFn: (color: string) => string
  kpiBorderTop: (color: string) => string
  kpiShadowFn: (color: string) => string
  kpiAccentFn: (color: string) => string

  // Chart functions
  chartBorderTop: (color: string) => string
  accentBgFn: (color: string) => string

  // ECharts-specific
  echartsBg: string
  echartsTextColor: string
  echartsAxisColor: string
  echartsSplitColor: string
  echartsTooltipBg: string
  echartsTooltipBorder: string
  echartsTooltipText: string
  echartsLegendText: string
}

